      "verso": "O raio DIMINUI: o número de camadas não muda, mas a carga nuclear crescente atrai mais a eletrosfera. A eletronegatividade AUMENTA pelo mesmo motivo. Confundir número de camadas com tamanho do átomo é o erro mais comum nessa comparação."
