      "verso": "A geometria MOLECULAR é definida pelas posições dos ÁTOMOS, não dos pares eletrônicos. Metano não tem par isolado: tetraédrico. Amônia tem um: piramidal. Água tem dois: angular. Confundir arranjo eletrônico com geometria molecular é o erro clássico."
