      "verso": "Ordem global 3 (soma dos expoentes: 1 + 2). Como B está elevado ao quadrado, dobrar sua concentração multiplica a velocidade por 2² = 4 — QUADRUPLICA. Aplicar o efeito como se o expoente de B fosse 1 é o erro que a questão testa deliberadamente."
