      "verso": "Diminui — é o efeito do íon comum. O equilíbrio de dissolução se desloca no sentido do sólido, reduzindo a solubilidade. O produto de solubilidade (Kps) permanece constante à mesma temperatura; o que muda é a distribuição entre os íons, não a constante em si."
